"""Regenerate compact_ecb_vectors.h with independent PyCryptodome AES.

Run with tests/requirements.txt installed. Ordinary C tests use the checked-in
header and need no Python or reference library at build/run time.
"""
from pathlib import Path

from Cryptodome.Cipher import AES


def generate():
    lines = [
        "/* Generated by tests/generate_compact_vectors.py; do not hand-edit.",
        " * Independent reference: PyCryptodome AES-ECB.",
        " * Variable-key inputs: key bit i is set (LSB first in each byte),",
        " * with an all-zero plaintext. Variable-plaintext inputs reverse this",
        " * construction, with an all-zero key of the configured size.",
        " */",
        "#ifndef AES_DUST_COMPACT_ECB_VECTORS_H",
        "#define AES_DUST_COMPACT_ECB_VECTORS_H",
    ]
    for key_length in [16, 32]:
        lines.append(("#if" if key_length == 16 else "#elif") + f" AES_KEY_LEN == {key_length}")
        for name, variable_key in [("compact_variable_key", True), ("compact_variable_plain", False)]:
            count = key_length * 8 if variable_key else 128
            lines.append(f"static const uint8_t {name}[{count}][16] = {{")
            for bit in range(count):
                key = bytearray(key_length)
                plain = bytearray(16)
                (key if variable_key else plain)[bit // 8] = 1 << (bit % 8)
                crypt = AES.new(bytes(key), AES.MODE_ECB).encrypt(bytes(plain))
                lines.append("    {" + ",".join(f"0x{x:02x}" for x in crypt) + "},")
            lines.append("};")
    lines.extend(["#else", '#error "Unsupported compact AES key size"', "#endif", "#endif", ""])
    return "\n".join(lines)


if __name__ == "__main__":
    with Path(__file__).with_name("compact_ecb_vectors.h").open("w", encoding="ascii", newline="\n") as output:
        output.write(generate())
